INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", 62, 1000001, "カリン", "2030/01/01 14:59:59", 1, "2025/01/31 12:00:00", 1, 1, 3.414, 2, 190805, -416.5);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "ミッションをクリアして、\n報酬をゲットしましょう！", 62, 1000002, "カリン", "2030/01/01 14:59:59", 1, "2025/01/31 12:00:00", 2, 1, 3.099, 2, 190805, -416.5);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "受け取ることができる\n報酬があるようです\n確認してみてください", 63, 1000003, "カリン", "2030/01/01 14:59:59", 1, "2025/01/31 12:00:00", 3, 1, 2.801, 2, 190805, -416.5);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "報酬がもらえますよ！\nチェックしてみてください", 63, 1000004, "カリン", "2030/01/01 14:59:59", 2, "2025/01/31 12:00:00", 4, 1, 0.0, 2, 190805, -416.5);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "ギルド管理協会です！\nイベント報酬券をお持ちでしたら、様々なアイテムと交換できますよ", 64, 1000005, "カリン", "2030/01/01 14:59:59", 2, "2025/01/31 12:00:00", 5, 1, 2.12, 1, 190805, -363.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "お疲れさまです！\nこちらでイベント報酬券とアイテムを交換することができますよ", 64, 1000006, "カリン", "2030/01/01 14:59:59", 1, "2025/01/31 12:00:00", 6, 1, 1.68, 2, 190805, -363.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "いつもありがとうございます！\n報酬交換ですか？\nでは、イベント報酬券とお引き換えいたしますね", 64, 1000007, "カリン", "2030/01/01 14:59:59", 2, "2025/01/31 12:00:00", 7, 1, 2.33, 1, 190805, -363.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (-6.0, "今度の敵は、アタシにとっても\n放ってはおけない存在だ\n少年、アタシも全力で行くからさ\n一緒に守ろう、この世界を", 61, 1020101, "ラビリスタ", "2030/01/01 14:59:59", 3, "2025/01/31 12:00:00", 101, 10201, 5.18, 7, 133701, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (-2.0, "退屈の吹き飛ぶような\n戦いの気配がするなぁ坊や\nさっさとワタシをそこへ連れてゆけ\n世界も守ってやるさ、ついでにな", 61, 1020102, "クリスティーナ", "2030/01/01 14:59:59", 1, "2025/01/31 12:00:00", 201, 10201, 8.77, 2, 133901, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "おや、私の力が必要……と？\nグレゴールが手伝うそうですよ\n私は戦わないのか、という顔ですね\n……考えておきます", 61, 1020103, "ネネカ", "2030/01/01 14:59:59", 6, "2025/01/31 12:00:00", 301, 10201, 15.5, 1, 133801, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "わたしだけの歌…\n一緒に、探してくれる…？\nあなたがいれば…\nもっとがんばれるから…", 61, 1020201, "ランファ", "2030/01/01 14:59:59", 2, "2025/02/28 12:00:00", 101, 10202, 9.061, 5, 134301, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "同じ唱喚士として、仲間として\n私にできることをします\n…これも、あなたが\n背中を押してくれたおかげですよ", 61, 1020202, "チカ", "2030/01/01 14:59:59", 1, "2025/02/28 12:00:00", 201, 10202, 7.699, 2, 134401, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "世界の平和が私とクローチェさんに\nかかってるんですよね？\nぼっちには過大すぎる期待ですけど\nふ、二人でなら背負ってみせます！", 61, 1020301, "アオイ", "2030/01/01 14:59:59", 1, "2025/03/31 12:00:00", 101, 10203, 8.595, 2, 134601, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "新しく手に入れたこの翼で…\nナイトさんがどこにいたって\nわたし、駆けつけちゃいますよっ！\nクローチェ・エアリアル発進ですっ", 61, 1020302, "クローチェ", "2030/01/01 14:59:59", 1, "2025/03/31 12:00:00", 201, 10203, 7.758, 2, 134501, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "今日はダーリンとの初デート♪\n二人でショッピングして、その後は\n…って私、指名手配されてる！？\nちょ、た…助けてダーリン～！！", 61, 1020401, "ルイズマリー", "2030/01/01 14:59:59", 2, "2025/04/30 12:00:00", 101, 10204, 7.0, 6, 132302, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "ルイちゃんのおばあちゃん優しくて\nいつもにこにこで、イロハ大好き♪\nでも一番好きなのは、角がすっごく\n大きくてかっこいいとこなんだ～♪", 61, 1020402, "イロハ", "2030/01/01 14:59:59", 1, "2025/04/30 12:00:00", 201, 10204, 7.904, 2, 132402, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "ノゾミちゃんのおかげで売上が安定\nしてきたのに、臨時休業、痛すぎる\n…ま、ルイちゃんのために\n一肌脱ぐか。行くよイロハ～", 61, 1020403, "ソノ", "2030/01/01 14:59:59", 4, "2025/04/30 12:00:00", 301, 10204, 8.487, 2, 132502, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "ヲ～ッホッホ♪\nあたくし様と同じお空気を吸える\nお幸運を噛みしめなさいですわ～♪\nヲ～ッホッホッホ～♪", 61, 1020502, "カノン", "2030/01/01 14:59:59", 1, "2025/05/31 12:00:00", 101, 10205, 8.763, 2, 134901, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "いきますよ騎士さん！\nカノンさんと力を合わせて…力を…\n…本当にあの人なんなんです？\nこれまでになく不安なんですけど！", 61, 1020503, "ツムギ", "2030/01/01 14:59:59", 1, "2025/05/31 12:00:00", 201, 10205, 6.417, 3, 134801, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "『願いが叶う海岸』か…怪しい\nだというのに、阿賀斗紫布菜たちは\n呑気に戯れている…見ていられない\n騎士クンは、わたしが守ってみせる", 61, 1020601, "エリス", "2030/01/01 14:59:59", 3, "2025/06/30 12:00:00", 101, 10206, 10.335, 7, 135001, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "せっかくの夏休みなんだし\nたまにはビーチでゆっくりしましょ\n…え、もしかしてこの夏もあんまり\n休めなかったりする感じなの？", 61, 1020602, "シェフィ", "2030/01/01 14:59:59", 2, "2025/06/30 12:00:00", 201, 10206, 6.281, 4, 135101, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "いっぱい。たべて\nおおきく。なると\nせーぎ。まもれる。はず\nお兄。いっしょに。スイカ。たべよ", 61, 1020603, "プレシア", "2030/01/01 14:59:59", 1, "2025/06/30 12:00:00", 301, 10206, 12.244, 2, 135201, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "ひと夏の冒険のはじまりです！\nアネモネさんも楽しんでくれたら\n…できれば、もう少し\n仲良くなれたらうれしいな…", 61, 1020701, "クリア", "2030/01/01 14:59:59", 2, "2025/07/31 12:00:00", 101, 10207, 6.339, 8, 135301, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "─幻の花…\n本当にあるのか謎─ですけど\n探すくらいは、\n付き合ってもいいです", 61, 1020702, "アネモネ", "2030/01/01 14:59:59", 7, "2025/07/31 12:00:00", 201, 10207, 8.184, 9, 135401, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "あははっ！　笑う門には福来る！\n笑ってればきっと、複製世界にも\n未来はやってくるって信じてる！\nそうだよね、シナツちゃん！", 61, 1020801, "アイラ", "2030/01/01 14:59:59", 9, "2025/08/31 12:00:00", 101, 10208, 3.906, 2, 129101, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "繰り返されるリセットの先の未来\n何度願っても手に入らなかった未来\n…でも、私は諦めない。絶対にだ\nキミも同じだろ…アイラ？", 61, 1020802, "シナツ", "2030/01/01 14:59:59", 1, "2025/08/31 12:00:00", 201, 10208, 14.465, 2, 129201, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "アイラの世界のみんなも、\n一生懸命生きてるんだ…！\n…なのに、世界の危機だなんて！\nあたし、絶対、絶対力になるよ！", 61, 1020803, "ヒヨリ", "2030/01/01 14:59:59", 4, "2025/08/31 12:00:00", 301, 10208, 8.662, 3, 100101, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "シナツ…もう一人の私\n彼女が大切にしている世界を\n絶対に終わらせはしない…！\n彼女と笑い合える未来のために！", 61, 1020804, "レイ", "2030/01/01 14:59:59", 1, "2025/08/31 12:00:00", 401, 10208, 10.915, 3, 100301, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "あ、ど、ども…\nあ、あんま見ねぇでくれっと\nその、恥ずかしくて…\n体が熱くなって、溶けちまう…", 61, 1020901, "ユキノ", "2030/01/01 14:59:59", 1, "2025/09/30 12:00:00", 101, 10209, 6.042, 7, 135802, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "なんで俺が幽霊に…意味不明だ\nこれじゃ死んでも死にきれねェ\n悪ィがこれも何かの縁だ、\nよろしく頼むぜ騎士公", 61, 1020902, "サツキ", "2030/01/01 14:59:59", 4, "2025/09/30 12:00:00", 201, 10209, 9.402, 1, 135903, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "う、うじゅる…\nサツキ姉しゃまを助けるためにも\nまずは、腹ごしらえでしゅね…！\nタコ焼き、召し上がってくだしゃい", 61, 1020903, "ルルィ", "2030/01/01 14:59:59", 8, "2025/09/30 12:00:00", 301, 10209, 8.16, 1, 136902, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "ひさしぶりのジオ・ゲヘナ\n歓迎パーティーで起きた殺人事件！\nランドソルの名探偵の名にかけて\n解き明かしてみせようじゃないか！", 61, 1021001, "カスミ", "2030/01/01 14:59:59", 3, "2025/10/31 12:00:00", 101, 10210, 5.0, 2, 137401, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "…わたしはどこの誰なのでしょう\nどこから来てどこへ行くのでしょう\nこの事件の真相が分かれば、\n何かが掴めるような気がいたします", 61, 1021002, "アラクネ", "2030/01/01 14:59:59", 4, "2025/10/31 12:00:00", 201, 10210, 8.12, 1, 136001, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "ナーナ、すいりとかろんぱとか、\nむずかしくてわかんないけど…\nお友だちとドーナツのためならっ\nせーいっぱいがんばるよっ！", 61, 1021003, "ナーナ", "2030/01/01 14:59:59", 4, "2025/10/31 12:00:00", 301, 10210, 6.386, 2, 136202, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "騎士クンに想いを伝えたい…だから\nミソラちゃん、わたしがんばるね！\n…あれ？　わたし、なんでこんなに\n必死になってるんだろう…？", 61, 1021101, "ユイ", "2030/01/01 14:59:59", 3, "2025/11/30 12:00:00", 101, 10211, 7.438, 4, 136402, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "騎士さんとのデートはわたしに\nお任せです★　なのでユイさんは\n安心して計画に専念して…たくさん\nドキドキしちゃってくださいね", 61, 1021102, "ミソラ", "2030/01/01 14:59:59", 1, "2025/11/30 12:00:00", 201, 10211, 8.35, 5, 136302, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "新しい年がやってくるね！\nお正月の料理も飾りつけも、\nお姉ちゃんにお任せだよ♪\nみんなで楽しく新年を迎えよう！", 61, 1021201, "シズル", "2030/01/01 14:59:59", 1, "2025/12/31 12:00:00", 101, 10212, 5.0, 2, 136501, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "おうちの掃除もトラブルも、 \n世界を揺るがす大ピンチも！\n今年のことは今年のうちに \nサッサと片付けちゃいますっ！", 61, 1021202, "リノ", "2030/01/01 14:59:59", 1, "2025/12/31 12:00:00", 201, 10212, 5.25, 2, 137902, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "年の瀬はギルドマスターも\nつい駆け回っちゃう忙しい時期だ！\n一年いろいろあったけど\nお互いイイ年を迎えよう、少年！", 61, 1021203, "ラビリスタ", "2030/01/01 14:59:59", 1, "2025/12/31 12:00:00", 301, 10212, 7.5, 2, 106801, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "漂う異国の料理の香り…それだけで\n世界中を旅した気分に浸れますね\nふふ、ほらクローチェ\nあまりはしゃぎすぎないように…♪", 61, 1021301, "ライラエル", "2030/01/01 14:59:59", 1, "2026/01/31 12:00:00", 101, 10213, 8.204, 2, 126501, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "異界の姫君と煮炊きにて競い合う…\n感奮興起、いとをかし\n華やかなる祭典と相成るよう、一肌\n脱がせていただきとう存じまする", 61, 1021302, "ネフィ＝ネラ", "2030/01/01 14:59:59", 1, "2026/01/31 12:00:00", 201, 10213, 7.176, 2, 129701, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "『ビストロプリンセス』のために\n料理の特訓を重ねてまいりました\nこの料理で騎士様の…い、いえ\n皆様の心とお腹を満たしますわ！", 61, 1021303, "ヴァイオレット", "2030/01/01 14:59:59", 1, "2026/01/31 12:00:00", 301, 10213, 8.602, 5, 133101, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "多様な味わいが織りなすハーモニー\nそれこそが我が国の矜持です\nもしもそれを乱すようであれば\nわたしも優しくはありませんよ？", 61, 1021304, "ライラエル", "2030/01/01 14:59:59", 1, "2026/02/06 12:00:00", 102, 10213, 10.14, 3, 138101, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "煉獄の穢土にてひと際輝く民草の心\n此れを守護りまするがわっちの責務\n如何な困難待ち受けようと\n不退転の矜持に揺らぎはありんせん", 61, 1021305, "ネフィ＝ネラ", "2030/01/01 14:59:59", 1, "2026/02/06 12:00:00", 202, 10213, 10.152, 7, 138201, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "裏世界の皆様は危機を脱し、\n残るはランドソルの皆様のみ…\n彼らを救い出すために、どうか…\nお立ち下さいペコリーヌ姫…！", 61, 1021306, "ヴァイオレット", "2030/01/01 14:59:59", 4, "2026/02/06 12:00:00", 302, 10213, 9.688, 3, 138001, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "みなさん、お待たせしちゃいました\nペコリーヌ、完全復活です☆\nみなさんの食卓を守るため\nもう二度と、わたしはめげません！", 61, 1021307, "ペコリーヌ", "2030/01/01 14:59:59", 2, "2026/02/12 12:00:00", 401, 10213, 5.928, 1, 138301, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "成行きで参加することになっちゃっ\nた尻相撲大会。ううっ、恥ずかしい\nけどやるしかないよね。…騎士さん\nいっぱい応援してくださいね？", 61, 1021401, "ワカナ", "2030/01/01 14:59:59", 4, "2026/02/28 12:00:00", 101, 10214, 9.19, 2, 138702, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "「お姉ちゃんを守れる自分になる」\nあの日の約束、今こそ果たしてみせ\nます。例えお姉ちゃんに背くことに\nなっても。例えそれが尻相撲でも！", 61, 1021402, "シオリ", "2030/01/01 14:59:59", 1, "2026/02/28 12:00:00", 201, 10214, 8.724, 3, 138802, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "私がへんたいふしんしゃさんって…\nただ生きているだけなのに、ひどい\n…まぁ死んでるんですけど…とか\n言ってる暇もない感じですか？", 61, 1021501, "グレイス", "2030/01/01 14:59:59", 4, "2026/03/31 12:00:00", 101, 10215, 7.758, 1, 138902, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "あの、助けてください！\n私がへんたいふしんしゃさんに\nなっちゃったみたいなんです…！\nどういう意味かは私もわかりません", 61, 1021502, "キョウカ", "2030/01/01 14:59:59", 6, "2026/03/31 12:00:00", 201, 10215, 6.375, 4, 139002, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "ましゃか、グレイス姉しゃまたちが\nへんたいふしんしゃさんだなんて…\n騎士しゃん。あたちたちも協力ちて\n二人の破滅エンドを回避ちましょう", 61, 1021503, "ルルィ", "2030/01/01 14:59:59", 6, "2026/03/31 12:00:00", 301, 10215, 6.173, 1, 136902, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "違う世界に来ちゃうし、\n驚きの連続だけど…\nわたしも精いっぱい頑張ります！\nアストルムのみんなと一緒に！", 61, 1021601, "ミホ", "2030/01/01 14:59:59", 6, "2026/04/30 12:00:00", 101, 10216, 4.202, 2, 139202, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "想定外の事象が発生したな…だが\nいかなる苦境も切り抜けてみせる\nいつもの自分とは違う姿になっても\nわたしはわたし、西住流だ", 61, 1021602, "マホ", "2030/01/01 14:59:59", 6, "2026/04/30 12:00:00", 201, 10216, 2.842, 1, 139302, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "何でこんなことになっているのか\n全然わからないけど、迷ってる暇は\nないわ。黒森峰の次期隊長として、\n前進あるのみ！　これも戦車道よ！", 61, 1021603, "エリカ", "2030/01/01 14:59:59", 4, "2026/04/30 12:00:00", 301, 10216, 4.598, 1, 139402, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "わたくしたちの悲願は、ロストさせ\nてしまった方々をお助けすること…\nそのためなら、どのような辛苦にも\n耐え抜いてみせます…！", 61, 1021701, "リリ", "2030/01/01 14:59:59", 4, "2026/05/31 12:00:00", 101, 10217, 6.533, 3, 125802, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "みんなも。せーぎも。\nクリアも。パパ、も。\nぜったい、たすける。\nみててね。お兄。", 61, 1021702, "プレシア", "2030/01/01 14:59:59", 3, "2026/05/31 12:00:00", 301, 10217, 5.0, 3, 126102, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "癒しの力を使うこと…\nもう、ためらいません！\nモネちゃんやお兄さん…\nみんなに許してもらうためにも！", 61, 1021703, "クリア", "2030/01/01 14:59:59", 3, "2026/05/31 12:00:00", 201, 10217, 5.214, 4, 126002, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "ヴァルキュリア─皆様を助けたい\nという願いを、力にできるのなら…\nわたくしたちは、きっと誰にも\n負けません！　一意専心です…！", 61, 1021704, "リリ", "2030/01/01 14:59:59", 1, "2026/05/31 12:00:00", 102, 10217, 8.781, 3, 139501, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "このヴァルキュリアって職業、\nまるで天使みたいな格好ですよね\nうーん…『聖女』ちゃんって\n呼ばれるよりは、マシかな？", 61, 1021705, "クリア", "2030/01/01 14:59:59", 2, "2026/05/31 12:00:00", 202, 10217, 6.529, 1, 139601, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "ばるきり。もーど。\nはね。まっしろ。\nはっぴーちゃんと。おなじ。\nいいかんじ。", 61, 1021706, "プレシア", "2030/01/01 14:59:59", 3, "2026/05/31 12:00:00", 302, 10217, 3.195, 2, 139701, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "ダーリンと一緒に南の島で\nリゾート開発なんて夢みたい♪\nああ…幸せ、最高の夏だわ…\n触れたら爆発さえしなければ～…っ", 61, 1021801, "ルイズマリー", "2030/01/01 14:59:59", 2, "2026/06/30 12:00:00", 101, 10218, 12.43, 3, 139902, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "青い空、白い雲…無人島リゾートで\n大儲けですわ～♪　こらこらそこ、\nイチャついてるんじゃないですのよ\n触れたらドカンですわよ、ドカン！", 61, 1021802, "クレジッタ", "2030/01/01 14:59:59", 2, "2026/06/30 12:00:00", 201, 10218, 6.35, 3, 140001, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "みんなはかわいいぼくを見られて、\nぼくはみんなからラヴをもらう♡\n最高のウィンウィンだよね、これ♡\nで、最後はお兄さんをドレーに…♡", 61, 1021901, "フブキ", "2030/01/01 14:59:59", 1, "2026/07/31 12:00:00", 101, 10219, 10.23, 5, 140102, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "けんぞくとたくさん遊ぶためにも、\nみんなからラヴをもらわなくちゃ♪\nバズっちゃおー作戦、\n一緒に考えてね！　けんぞくぅ♪", 61, 1021902, "ヴァンピィ", "2030/01/01 14:59:59", 1, "2026/07/31 12:00:00", 201, 10219, 5.584, 2, 140201, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", 62, 2000001, "カリン", "2030/01/01 14:59:59", 1, "2026/04/10 12:00:00", 1, 2, 3.414, 2, 190801, -416.5);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "ミッションをクリアして、\n報酬をゲットしましょう！", 62, 2000002, "カリン", "2030/01/01 14:59:59", 1, "2026/04/10 12:00:00", 2, 2, 3.099, 2, 190801, -416.5);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "受け取ることができる\n報酬があるようです\n確認してみてください", 63, 2000003, "カリン", "2030/01/01 14:59:59", 1, "2026/04/10 12:00:00", 3, 2, 2.801, 2, 190801, -416.5);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "報酬がもらえますよ！\nチェックしてみてください", 63, 2000004, "カリン", "2030/01/01 14:59:59", 2, "2026/04/10 12:00:00", 4, 2, 0.0, 2, 190801, -416.5);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "ギルド管理協会です！\nイベント報酬券をお持ちでしたら、様々なアイテムと交換できますよ", 64, 2000005, "カリン", "2030/01/01 14:59:59", 2, "2026/04/10 12:00:00", 5, 2, 2.12, 1, 190801, -363.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "お疲れさまです！\nこちらでイベント報酬券とアイテムを交換することができますよ", 64, 2000006, "カリン", "2030/01/01 14:59:59", 1, "2026/04/10 12:00:00", 6, 2, 1.68, 2, 190801, -363.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "いつもありがとうございます！\n報酬交換ですか？\nでは、イベント報酬券とお引き換えいたしますね", 64, 2000007, "カリン", "2030/01/01 14:59:59", 2, "2026/04/10 12:00:00", 7, 2, 2.33, 1, 190801, -363.0);
